document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("passive-income-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("rentalIncome").value)||0,t=parseFloat(document.getElementById("rentalGrowth").value)/100||0,r=parseFloat(document.getElementById("dividendIncome").value)||0,o=parseFloat(document.getElementById("dividendGrowth").value)/100||0,a=parseFloat(document.getElementById("businessIncome").value)||0,i=parseFloat(document.getElementById("businessGrowth").value)/100||0,d=parseFloat(document.getElementById("digitalIncome").value)||0,s=parseFloat(document.getElementById("digitalGrowth").value)/100||0,l=parseFloat(document.getElementById("monthlyExpenses").value),u=parseInt(document.getElementById("yearProjection").value),c=n+r+a+d,g=12*c,m=n*Math.pow(1+t,u),h=r*Math.pow(1+o,u),p=a*Math.pow(1+i,u),v=d*Math.pow(1+s,u),b=m+h+p+v,y=12*b,$=c/l*100,M=b/l*100;let f=0;for(let e=1;e<=u;e++){f+=n*Math.pow(1+t,e)*12+r*Math.pow(1+o,e)*12+a*Math.pow(1+i,e)*12+d*Math.pow(1+s,e)*12}let w="",x="";$>=100?(w="🎉 You've achieved financial independence!",x="success"):M>=100?(w=`🎯 You'll achieve financial independence in ${u} years!`,x="info"):(w="📈 Keep building - you're on the right track!",x="warning");document.getElementById("passive-income-result").innerHTML=`\n      <h3>💰 Your Passive Income Analysis</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card info">\n          <h6>📊 Current Monthly Income</h6>\n          <div class="big-number">$${Math.round(c).toLocaleString()}</div>\n          <p>Covers ${Math.round($)}% of expenses<br>\n          Annual: $${Math.round(g).toLocaleString()}</p>\n        </div>\n        \n        <div class="insight-card ${x}">\n          <h6>🚀 Future Monthly Income (${u}Y)</h6>\n          <div class="big-number">$${Math.round(b).toLocaleString()}</div>\n          <p>Covers ${Math.round(M)}% of expenses<br>\n          Annual: $${Math.round(y).toLocaleString()}</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>💎 Total Projected Income</h6>\n          <div class="big-number">$${Math.round(f).toLocaleString()}</div>\n          <p>Cumulative over ${u} years<br>\n          Average/year: $${Math.round(f/u).toLocaleString()}</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>${w}</h4>\n        \n        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; margin-top: 1.5rem;">\n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px;">\n            <strong>🏠 Real Estate</strong><br>\n            Current: $${Math.round(n).toLocaleString()}/mo<br>\n            Future: $${Math.round(m).toLocaleString()}/mo<br>\n            <small style="color: #28a745;">+${(100*t).toFixed(1)}% annually</small>\n          </div>\n          \n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px;">\n            <strong>📈 Investments</strong><br>\n            Current: $${Math.round(r).toLocaleString()}/mo<br>\n            Future: $${Math.round(h).toLocaleString()}/mo<br>\n            <small style="color: #28a745;">+${(100*o).toFixed(1)}% annually</small>\n          </div>\n          \n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px;">\n            <strong>💼 Business</strong><br>\n            Current: $${Math.round(a).toLocaleString()}/mo<br>\n            Future: $${Math.round(p).toLocaleString()}/mo<br>\n            <small style="color: #28a745;">+${(100*i).toFixed(1)}% annually</small>\n          </div>\n          \n          <div style="text-align: center; padding: 1rem; background: white; border-radius: 8px;">\n            <strong>💡 Digital/Royalties</strong><br>\n            Current: $${Math.round(d).toLocaleString()}/mo<br>\n            Future: $${Math.round(v).toLocaleString()}/mo<br>\n            <small style="color: #28a745;">+${(100*s).toFixed(1)}% annually</small>\n          </div>\n        </div>\n        \n        <div style="margin-top: 1.5rem; padding: 1rem; background: #e3f2fd; border-radius: 8px; border-left: 4px solid #2196f3;">\n          <strong>💡 Next Steps:</strong><br>\n          ${$<100?"• Focus on increasing your highest-growth streams<br>\n             • Consider reducing expenses to reach independence sooner<br>\n             • Reinvest profits to accelerate growth<br>\n             • Diversify into new income streams when possible":"• Congratulations on achieving financial independence!<br>\n             • Continue growing your passive income for security<br>\n             • Consider helping others achieve the same goal<br>\n             • Enjoy the freedom you've created!"}\n        </div>\n      </div>\n    `})});